import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler
from sklearn.model_selection import StratifiedKFold
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Check for correlation pairs and remove near-duplicates
    correlated_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if feats.column(fid1) < feats.x.shape[1] and feats.column(fid2) < feats.x.shape[1]:
                corr = np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]
                if abs(corr) >= 0.6:
                    correlated_pairs.add((min(fid1, fid2), max(fid1, fid2)))

    # Remove near-duplicates, keeping first occurrence
    used_ids = set()
    unique_ids = []
    for fid in feats.ids:
        # Check if any correlated pair involves this feature
        is_duplicate = False
        for pair in correlated_pairs:
            if fid in pair:
                # Keep the first feature in the pair
                if pair[0] == fid:
                    unique_ids.append(fid)
                elif pair[1] == fid and pair[0] not in used_ids:
                    unique_ids.append(fid)
                is_duplicate = True
                break
        if not is_duplicate:
            unique_ids.append(fid)
        used_ids.add(fid)

    # Build a mapping from feature id to its index in unique_ids
    feat_to_idx = {fid: i for i, fid in enumerate(unique_ids)}

    # Calculate correlations between features and outcome
    feature_scores = []
    for fid in unique_ids:
        col_idx = feats.column(fid)
        if col_idx < feats.x.shape[1]:
            # Use Welch's t-test for significance
            y0 = feats.x[feats.y == 0, col_idx]
            y1 = feats.x[feats.y == 1, col_idx]
            if len(y0) > 0 and len(y1) > 0:
                t_stat, p_val = stats.ttest_ind(y0, y1, equal_var=False)
                # Use difference in means as proxy for effect size
                diff_mean = np.mean(y1) - np.mean(y0)
                feature_scores.append((fid, abs(diff_mean), p_val))

    # Sort by effect size (descending) and then by significance (ascending)
    feature_scores.sort(key=lambda x: (-x[1], x[2]))

    # Try to identify drivers using stratified analysis
    drivers = []
    if len(feature_scores) > 0:
        # For each feature, check if it shows consistent effect across strata
        stratum_effects = defaultdict(list)
        for stratum in set(feats.stratum):
            mask = np.array([s == stratum for s in feats.stratum])
            if np.sum(mask) > 1:
                y_stratum = feats.y[mask]
                for fid, _, _ in feature_scores[:10]:  # Top 10 features
                    col_idx = feats.column(fid)
                    if col_idx < feats.x.shape[1]:
                        x_stratum = feats.x[mask, col_idx]
                        if len(x_stratum[y_stratum == 1]) > 0 and len(x_stratum[y_stratum == 0]) > 0:
                            t_stat, _ = stats.ttest_ind(
                                x_stratum[y_stratum == 1],
                                x_stratum[y_stratum == 0],
                                equal_var=False
                            )
                            stratum_effects[fid].append(t_stat)

        # Select features that show consistent effects across strata
        for fid, _, _ in feature_scores[:10]:
            if len(stratum_effects[fid]) >= 2:  # At least 2 strata
                std_dev = np.std(stratum_effects[fid])
                mean_effect = np.mean(stratum_effects[fid])
                if abs(mean_effect) > 1.5 and std_dev < 2.0:  # Consistent effect
                    drivers.append(fid)
                    if len(drivers) >= MAX_DRIVERS:
                        break

    # If no drivers found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select features for regression (include drivers and some related features)
    columns = []
    for fid in unique_ids:
        if fid in drivers or any(pair[0] == fid or pair[1] == fid for pair in correlated_pairs):
            columns.append(fid)

    # Create interaction terms
    products = []
    for i, fid1 in enumerate(columns):
        for j, fid2 in enumerate(columns[i+1:], i+1):
            if (fid1, fid2) not in correlated_pairs and (fid2, fid1) not in correlated_pairs:
                products.append((fid1, fid2))

    # Weighted score based on effect sizes
    loadings = {}
    for fid in columns:
        col_idx = feats.column(fid)
        if col_idx < feats.x.shape[1]:
            y0 = feats.x[feats.y == 0, col_idx]
            y1 = feats.x[feats.y == 1, col_idx]
            if len(y0) > 0 and len(y1) > 0:
                diff_mean = np.mean(y1) - np.mean(y0)
                loadings[fid] = abs(diff_mean)

    # Normalize loadings
    total = sum(loadings.values())
    if total > 0:
        for k in loadings:
            loadings[k] /= total

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

